from .common import make_sol

TRIES_SOLUTIONS = {
    'bit-prerequisites-for-trie-problems': make_sol('public class Solution {\n    // Demonstration of Bit Manipulation prerequisites for Trie XOR problems\n    public static int checkBit(int num, int i) {\n        return (num >> i) & 1;\n    }\n}', 'O(1)', 'O(1)', 'public class Solution {\n    public static int checkBit(int num, int i) {\n        return (num >> i) & 1;\n    }\n}', 'O(1)', 'O(1)'),

    'trie-implementation-and-operations': make_sol("public class Solution {\n    static class TrieNode {\n        TrieNode[] children = new TrieNode[26];\n        boolean isEnd;\n    }\n\n    static class Trie {\n        TrieNode root = new TrieNode();\n\n        public void insert(String word) {\n            TrieNode node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.children[idx] == null) node.children[idx] = new TrieNode();\n                node = node.children[idx];\n            }\n            node.isEnd = true;\n        }\n\n        public boolean search(String word) {\n            TrieNode node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.children[idx] == null) return false;\n                node = node.children[idx];\n            }\n            return node.isEnd;\n        }\n\n        public boolean startsWith(String prefix) {\n            TrieNode node = root;\n            for (char c : prefix.toCharArray()) {\n                int idx = c - 'a';\n                if (node.children[idx] == null) return false;\n                node = node.children[idx];\n            }\n            return true;\n        }\n    }\n}", 'O(L)', 'O(L * 26)', "public class Solution {\n    static class TrieNode {\n        TrieNode[] children = new TrieNode[26];\n        boolean isEnd;\n    }\n\n    static class Trie {\n        TrieNode root = new TrieNode();\n\n        public void insert(String word) {\n            TrieNode node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.children[idx] == null) node.children[idx] = new TrieNode();\n                node = node.children[idx];\n            }\n            node.isEnd = true;\n        }\n\n        public boolean search(String word) {\n            TrieNode node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.children[idx] == null) return false;\n                node = node.children[idx];\n            }\n            return node.isEnd;\n        }\n\n        public boolean startsWith(String prefix) {\n            TrieNode node = root;\n            for (char c : prefix.toCharArray()) {\n                int idx = c - 'a';\n                if (node.children[idx] == null) return false;\n                node = node.children[idx];\n            }\n            return true;\n        }\n    }\n}", 'O(L)', 'O(L * 26)'),

    'trie-implementation-and-advanced-operations': make_sol("public class Solution {\n    static class Node {\n        Node[] links = new Node[26];\n        int countPrefix = 0;\n        int countEndsWith = 0;\n    }\n\n    static class Trie {\n        Node root = new Node();\n\n        public void insert(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.links[idx] == null) node.links[idx] = new Node();\n                node = node.links[idx];\n                node.countPrefix++;\n            }\n            node.countEndsWith++;\n        }\n\n        public int countWordsEqualTo(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.links[idx] == null) return 0;\n                node = node.links[idx];\n            }\n            return node.countEndsWith;\n        }\n\n        public int countWordsStartingWith(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.links[idx] == null) return 0;\n                node = node.links[idx];\n            }\n            return node.countPrefix;\n        }\n\n        public void erase(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                node = node.links[idx];\n                node.countPrefix--;\n            }\n            node.countEndsWith--;\n        }\n    }\n}", 'O(L)', 'O(L * 26)', "public class Solution {\n    static class Node {\n        Node[] links = new Node[26];\n        int countPrefix = 0;\n        int countEndsWith = 0;\n    }\n\n    static class Trie {\n        Node root = new Node();\n\n        public void insert(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.links[idx] == null) node.links[idx] = new Node();\n                node = node.links[idx];\n                node.countPrefix++;\n            }\n            node.countEndsWith++;\n        }\n\n        public int countWordsEqualTo(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.links[idx] == null) return 0;\n                node = node.links[idx];\n            }\n            return node.countEndsWith;\n        }\n\n        public int countWordsStartingWith(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                if (node.links[idx] == null) return 0;\n                node = node.links[idx];\n            }\n            return node.countPrefix;\n        }\n\n        public void erase(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - 'a';\n                node = node.links[idx];\n                node.countPrefix--;\n            }\n            node.countEndsWith--;\n        }\n    }\n}", 'O(L)', 'O(L * 26)'),

    'longest-word-with-all-prefixes': make_sol('import java.util.Arrays;\nimport java.util.HashSet;\nimport java.util.Set;\n\npublic class Solution {\n    public static String completeString(int n, String[] a) {\n        Arrays.sort(a);\n        Set<String> set = new HashSet<>(Arrays.asList(a));\n        String longest = "";\n        for (String word : a) {\n            boolean valid = true;\n            for (int i = 1; i <= word.length(); i++) {\n                if (!set.contains(word.substring(0, i))) {\n                    valid = false;\n                    break;\n                }\n            }\n            if (valid) {\n                if (word.length() > longest.length()) longest = word;\n            }\n        }\n        return longest.isEmpty() ? "None" : longest;\n    }\n}', 'O(N * L²)', 'O(N * L)', 'public class Solution {\n    static class Node {\n        Node[] links = new Node[26];\n        boolean flag = false;\n    }\n\n    static class Trie {\n        Node root = new Node();\n\n        void insert(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - \'a\';\n                if (node.links[idx] == null) node.links[idx] = new Node();\n                node = node.links[idx];\n            }\n            node.flag = true;\n        }\n\n        boolean checkIfAllPrefixExists(String word) {\n            Node node = root;\n            for (char c : word.toCharArray()) {\n                int idx = c - \'a\';\n                if (node.links[idx] != null) {\n                    node = node.links[idx];\n                    if (!node.flag) return false;\n                } else return false;\n            }\n            return true;\n        }\n    }\n\n    public static String completeString(int n, String[] a) {\n        Trie trie = new Trie();\n        for (String word : a) trie.insert(word);\n        String longest = "";\n        for (String word : a) {\n            if (trie.checkIfAllPrefixExists(word)) {\n                if (word.length() > longest.length() || (word.length() == longest.length() && word.compareTo(longest) < 0)) {\n                    longest = word;\n                }\n            }\n        }\n        return longest.isEmpty() ? "None" : longest;\n    }\n}', 'O(N * L)', 'O(N * L)'),

    'number-of-distinct-substrings-in-a-string': make_sol('import java.util.HashSet;\nimport java.util.Set;\n\npublic class Solution {\n    public static int countDistinctSubstrings(String s) {\n        Set<String> set = new HashSet<>();\n        int n = s.length();\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j <= n; j++) {\n                set.add(s.substring(i, j));\n            }\n        }\n        return set.size() + 1;\n    }\n}', 'O(N³)', 'O(N³)', "public class Solution {\n    static class Node {\n        Node[] links = new Node[26];\n    }\n\n    public static int countDistinctSubstrings(String s) {\n        Node root = new Node();\n        int count = 0;\n        int n = s.length();\n        for (int i = 0; i < n; i++) {\n            Node node = root;\n            for (int j = i; j < n; j++) {\n                int idx = s.charAt(j) - 'a';\n                if (node.links[idx] == null) {\n                    node.links[idx] = new Node();\n                    count++;\n                }\n                node = node.links[idx];\n            }\n        }\n        return count + 1;\n    }\n}", 'O(N²)', 'O(N² * 26)'),

    'maximum-xor-of-two-numbers-in-an-array': make_sol('public class Solution {\n    public static int findMaximumXOR(int[] nums) {\n        int max = 0;\n        for (int i = 0; i < nums.length; i++) {\n            for (int j = i + 1; j < nums.length; j++) {\n                max = Math.max(max, nums[i] ^ nums[j]);\n            }\n        }\n        return max;\n    }\n}', 'O(N²)', 'O(1)', 'public class Solution {\n    static class Node {\n        Node[] links = new Node[2];\n    }\n\n    static class Trie {\n        Node root = new Node();\n\n        void insert(int num) {\n            Node node = root;\n            for (int i = 31; i >= 0; i--) {\n                int bit = (num >> i) & 1;\n                if (node.links[bit] == null) node.links[bit] = new Node();\n                node = node.links[bit];\n            }\n        }\n\n        int getMax(int num) {\n            Node node = root;\n            int maxNum = 0;\n            for (int i = 31; i >= 0; i--) {\n                int bit = (num >> i) & 1;\n                if (node.links[1 - bit] != null) {\n                    maxNum |= (1 << i);\n                    node = node.links[1 - bit];\n                } else {\n                    node = node.links[bit];\n                }\n            }\n            return maxNum;\n        }\n    }\n\n    public static int findMaximumXOR(int[] nums) {\n        Trie trie = new Trie();\n        for (int num : nums) trie.insert(num);\n        int max = 0;\n        for (int num : nums) max = Math.max(max, trie.getMax(num));\n        return max;\n    }\n}', 'O(32 * N)', 'O(32 * N)'),

    'maximum-xor-with-an-element-from-an-array': make_sol('public class Solution {\n    public static int[] maximizeXor(int[] nums, int[][] queries) {\n        int[] ans = new int[queries.length];\n        for (int q = 0; q < queries.length; q++) {\n            int x = queries[q][0], m = queries[q][1];\n            int max = -1;\n            for (int num : nums) {\n                if (num <= m) max = Math.max(max, num ^ x);\n            }\n            ans[q] = max;\n        }\n        return ans;\n    }\n}', 'O(Q * N)', 'O(1)', 'import java.util.Arrays;\nimport java.util.Comparator;\n\npublic class Solution {\n    static class Node { Node[] links = new Node[2]; }\n    static class Trie {\n        Node root = new Node();\n        void insert(int num) {\n            Node node = root;\n            for (int i = 31; i >= 0; i--) {\n                int bit = (num >> i) & 1;\n                if (node.links[bit] == null) node.links[bit] = new Node();\n                node = node.links[bit];\n            }\n        }\n        int getMax(int num) {\n            Node node = root;\n            if (node.links[0] == null && node.links[1] == null) return -1;\n            int maxNum = 0;\n            for (int i = 31; i >= 0; i--) {\n                int bit = (num >> i) & 1;\n                if (node.links[1 - bit] != null) {\n                    maxNum |= (1 << i);\n                    node = node.links[1 - bit];\n                } else {\n                    node = node.links[bit];\n                }\n            }\n            return maxNum;\n        }\n    }\n\n    public static int[] maximizeXor(int[] nums, int[][] queries) {\n        Arrays.sort(nums);\n        int q = queries.length;\n        int[][] offlineQueries = new int[q][3];\n        for (int i = 0; i < q; i++) {\n            offlineQueries[i][0] = queries[i][0];\n            offlineQueries[i][1] = queries[i][1];\n            offlineQueries[i][2] = i;\n        }\n        Arrays.sort(offlineQueries, Comparator.comparingInt(a -> a[1]));\n        int[] ans = new int[q];\n        Trie trie = new Trie();\n        int idx = 0, n = nums.length;\n        for (int i = 0; i < q; i++) {\n            int x = offlineQueries[i][0], m = offlineQueries[i][1], queryIdx = offlineQueries[i][2];\n            while (idx < n && nums[idx] <= m) {\n                trie.insert(nums[idx++]);\n            }\n            ans[queryIdx] = trie.getMax(x);\n        }\n        return ans;\n    }\n}', 'O(N log N + Q log Q + (N + Q) * 32)', 'O(N * 32)'),

}
